  async function openApplication(id:string){setSelectedApplication(null);setDetailError("");setReviewMessage("");setReviewReason("");setDetailLoading(true);try{const response=await fetch("/api/owner/applications/"+encodeURIComponent(id),{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Application details could not be loaded.");setSelectedApplication(data.application as ApplicationDetail);}catch(error){setDetailError(error instanceof Error?error.message:"Application details could not be loaded.");}finally{setDetailLoading(false);}}
  async function issueApplicationRecoveryLink(){if(!selectedApplication)return;setRecoveryBusy(true);setRecoveryMessage("");setRecoveryLink("");try{const response=await fetch("/api/owner/applications/"+encodeURIComponent(selectedApplication.id)+"/access-link",{method:"POST"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Recovery link could not be issued.");setRecoveryLink(window.location.origin+data.accessPath);setRecoveryMessage("A fresh private access link was created. It expires "+new Date(data.expiresAt).toLocaleString()+". Copy it and send it to the applicant using a private channel.");}catch(error){setRecoveryMessage(error instanceof Error?error.message:"Recovery link could not be issued.");}finally{setRecoveryBusy(false);}}
  async function reviewApplication(decision:"under_review"|"needs_information"|"approved"|"rejected"){if(!selectedApplication)return;if((decision==="rejected"||decision==="needs_information")&&!reviewReason.trim()){setReviewMessage("Please provide a reason for this decision.");return;}if(decision==="approved"&&!window.confirm("Approve this application and create its photographer record as Free and Unpublished?"))return;setReviewBusy(true);setReviewMessage("");try{const response=await fetch("/api/owner/applications/"+encodeURIComponent(selectedApplication.id)+"/review",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({decision,reason:reviewReason})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Application review could not be completed.");setSelectedApplication(v=>v?{...v,status:decision}:v);setApplications(v=>v.map(a=>a.id===selectedApplication.id?{...a,status:decision}:a));setReviewMessage(decision==="approved"?"Application approved. Photographer record created as Free and Unpublished. Photographer ID: "+(data.photographerId||"available in Photographers"):"Application status updated to "+decision.replaceAll("_"," ")+".");setReviewReason("");}catch(error){setReviewMessage(error instanceof Error?error.message:"Application review could not be completed.");}finally{setReviewBusy(false);}}
